/**
 * Explicit TypeScript interfaces for staff members (users).
 * Mirrors the DB schema's `users` table but is decoupled from Drizzle inference.
 */

export interface StaffMember {
  id: string
  name: string
  role: 'mechanic' | 'manager'
  hourlyRate: number // cents per hour
  isActive: boolean
  createdAt: Date
}

/** Input for creating a new staff member. */
export interface NewStaffMember {
  name: string
  role: 'mechanic' | 'manager'
  hourlyRate: number // cents per hour
  isActive?: boolean
}

/** Input for updating an existing staff member (partial). */
export interface UpdateStaffMember {
  name?: string
  role?: 'mechanic' | 'manager'
  hourlyRate?: number // cents per hour
  isActive?: boolean
}

import { z } from 'zod'

// ---------------------------------------------------------------------------
// Role enum
// ---------------------------------------------------------------------------

export const staffRoleSchema = z.enum(['mechanic', 'manager'])

/** A staff member role */
export type StaffRole = z.infer<typeof staffRoleSchema>

// ---------------------------------------------------------------------------
// Create input schema
// ---------------------------------------------------------------------------

/** Input for creating a new staff member. */
export const createStaffMemberSchema = z.object({
  id: z.string().uuid('id must be a valid UUID').optional(),
  name: z.string().min(1, 'name is required').max(200),
  role: staffRoleSchema.default('mechanic'),
  hourlyRate: z.number()
    .int('hourlyRate must be an integer (cents)')
    .positive('hourlyRate must be positive'),
  isActive: z.boolean().optional(),
})

/** Input for creating a new staff member. */
export type CreateStaffMemberInput = z.infer<typeof createStaffMemberSchema>

// ---------------------------------------------------------------------------
// Update input schema — partial fields, at least one required
// ---------------------------------------------------------------------------

const updatableFields = [
  'name', 'role', 'hourlyRate', 'isActive'
] as const

/** Input for updating an existing staff member (partial). */
export const updateStaffMemberSchema = z.object({
  name: z.string().min(1, 'name must not be empty').max(200).optional(),
  role: staffRoleSchema.optional(),
  hourlyRate: z.number()
    .int('hourlyRate must be an integer (cents)')
    .positive('hourlyRate must be positive')
    .optional(),
  isActive: z.boolean().optional(),
}).refine(
  data => updatableFields.some(key => data[key] !== undefined),
  { message: 'At least one field must be provided for update' }
)

/** Input for updating an existing staff member. */
export type UpdateStaffMemberInput = z.infer<typeof updateStaffMemberSchema>

/**
 * Users Routes — Worker lookup for repair assignment and staff management.
 */

import { Hono } from 'hono'
import {
  getActiveWorkers,
  listUsersPaginated,
  type StaffListQuery,
} from '../services/users.service.js'

const usersRoutes = new Hono()

// ---------------------------------------------------------------------------
// GET /users — Dual-mode endpoint
//
// When called without query parameters, returns a compact shape:
// id, name, role. Only active workers (isActive=true).
// Suitable for populating repair assignment dropdowns.
//
// When called with ?search= and/or ?page= parameters, returns full staff member
// details with pagination — suitable for the management list view.
// ---------------------------------------------------------------------------

usersRoutes.get('/', async (c) => {
  const search = c.req.query('search')
  const page = c.req.query('page')
  const pageSize = c.req.query('pageSize')

  // If pagination or search params are present, return paginated full details
  if (search !== undefined || page !== undefined || pageSize !== undefined) {
    const query: StaffListQuery = {}
    if (search !== undefined && search !== '') query.search = search
    if (page !== undefined) query.page = parseInt(page, 10)
    if (pageSize !== undefined) query.pageSize = parseInt(pageSize, 10)

    return c.json(await listUsersPaginated(query))
  }

  // Default: compact selector shape for POS dropdown consumers
  const workers = await getActiveWorkers()
  return new Response(JSON.stringify(workers), {
    headers: { 'Content-Type': 'application/json' },
  })
})

export default usersRoutes

/**
 * Users Service — Worker lookup for repair assignment and staff management.
 */

import { asc, eq, sql } from 'drizzle-orm'
import { db } from '../db/index.js'
import { users, type User as DbUser } from '../db/schema.js'

// ---------------------------------------------------------------------------
// Types — compact dropdown shape (existing)
// ---------------------------------------------------------------------------

/** Compact worker shape for dropdown selectors (name + role only) */
export interface WorkerOption {
  id: string
  name: string
  role: 'mechanic' | 'manager'
}

// ---------------------------------------------------------------------------
// Types — paginated management list
// ---------------------------------------------------------------------------

/** Full staff member detail for the management list. */
export interface StaffMemberDetail {
  id: string
  name: string
  role: 'mechanic' | 'manager'
  hourlyRate: number // cents per hour
  isActive: boolean
  createdAt: Date
}

/** Query parameters for the paginated staff list. */
export interface StaffListQuery {
  /** Search term — filters by name */
  search?: string
  /** Page number (1-indexed) */
  page?: number
  /** Items per page */
  pageSize?: number
}

/** Paginated response for the staff management list. */
export interface StaffPaginatedResponse {
  users: StaffMemberDetail[]
  totalItems: number
  currentPage: number
  pageSize: number
  totalPages: number
}

// ---------------------------------------------------------------------------
// Functions — compact dropdown (existing)
// ---------------------------------------------------------------------------

/**
 * List all active workers, suitable for populating a worker assignment dropdown.
 * Returns workers sorted by name for consistent display order.
 */
export async function getActiveWorkers(): Promise<WorkerOption[]> {
  const rows = await db
    .select({
      id: users.id,
      name: users.name,
      role: users.role,
    })
    .from(users)
    .where(eq(users.isActive, true))
    .orderBy(users.name)

  return rows as unknown as WorkerOption[]
}

// ---------------------------------------------------------------------------
// Functions — paginated management list
// ---------------------------------------------------------------------------

/**
 * Get paginated staff member list with optional search filtering.
 *
 * Returns full StaffMemberDetail records suitable for the management view.
 * Search filters by name using SQL LIKE. Includes both active and inactive members.
 *
 * @param query - Optional search term, page number, and page size
 * @returns Paginated response with staff members and pagination metadata
 */
export async function listUsersPaginated(
  query: StaffListQuery = {}
): Promise<StaffPaginatedResponse> {
  const { search, page = 1, pageSize = 25 } = query
  const offset = (page - 1) * pageSize

  // Build filter conditions for search
  let whereClause: ReturnType<typeof sql> | undefined

  if (search && search.trim()) {
    const term = `%${search.trim()}%`
    whereClause = sql`LOWER(${users.name}) LIKE ${term.toLowerCase()}`
  }

  // Get total count for pagination
  let totalCount = 0
  if (whereClause) {
    const [{ count }] = await db.select({ count: sql<number>`count(*)` }).from(users).where(whereClause)
    totalCount = count
  } else {
    const [{ count }] = await db.select({ count: sql<number>`count(*)` }).from(users)
    totalCount = count
  }

  // Get paginated results
  let results: DbUser[]
  if (whereClause) {
    results = await db.select().from(users).where(whereClause)
      .orderBy(asc(users.name))
      .limit(pageSize)
      .offset(offset)
  } else {
    results = await db.select().from(users)
      .orderBy(asc(users.name))
      .limit(pageSize)
      .offset(offset)
  }

  const totalPages = Math.max(1, Math.ceil(totalCount / pageSize))

  return {
    users: results.map(toStaffMemberDetail),
    totalItems: totalCount,
    currentPage: page,
    pageSize,
    totalPages,
  }
}

// ---------------------------------------------------------------------------
// Helpers — map between DB User and DTO shapes
// ---------------------------------------------------------------------------

/** Map a DB User to the full staff member detail shape. */
function toStaffMemberDetail(user: DbUser): StaffMemberDetail {
  return {
    id: user.id,
    name: user.name,
    role: user.role as 'mechanic' | 'manager',
    hourlyRate: user.hourlyRate,
    isActive: user.isActive,
    createdAt: user.createdAt,
  }
}

/**
 * Staff — API client functions.
 */

import type { StaffPaginatedResponse } from './types.js'

const BASE_URL = '' // relative to current origin

// ---------------------------------------------------------------------------
// Management List (paginated + searchable)
// ---------------------------------------------------------------------------

export async function fetchStaffMembers({
  search,
  page = 1,
  pageSize = 25,
}: {
  search?: string
  page?: number
  pageSize?: number
}): Promise<StaffPaginatedResponse> {
  const params = new URLSearchParams()

  if (search !== undefined && search !== '') {
    params.set('search', search)
  }
  params.set('page', String(page))
  params.set('pageSize', String(pageSize))

  const response = await fetch(`${BASE_URL}/api/users?${params}`)

  if (!response.ok) {
    const body = await response.json().catch(() => ({}))
    throw new Error((body as { error?: string }).error ?? `Failed to load staff members: ${response.status}`)
  }

  return response.json() as Promise<StaffPaginatedResponse>
}

/**
 * Staff — Frontend types.
 */

// ---------------------------------------------------------------------------
// Re-export shared domain types
// ---------------------------------------------------------------------------

export type { StaffMember, NewStaffMember, UpdateStaffMember } from '@shared/types/staff.js'

// ---------------------------------------------------------------------------
// Frontend DTOs (mirroring backend response shapes)
// ---------------------------------------------------------------------------

/** Full staff member detail returned by the paginated list endpoint. */
export interface StaffMemberDetail {
  id: string
  name: string
  role: 'mechanic' | 'manager'
  hourlyRate: number // cents per hour
  isActive: boolean
  createdAt: Date | string
  // Index signature required by DataTable<T extends Record<string, unknown>>
  [key: string]: unknown
}

/** Paginated response from the staff management list endpoint. */
export interface StaffPaginatedResponse {
  users: StaffMemberDetail[]
  totalItems: number
  currentPage: number
  pageSize: number
  totalPages: number
}

// ---------------------------------------------------------------------------
// Display helpers
// ---------------------------------------------------------------------------

/** Format hourly rate (cents) as currency string with /h suffix. */
export function formatHourlyRate(cents: number): string {
  const euros = cents / 100
  return `€${euros.toFixed(2)}/h`
}

/**
 * useStaffMembers — Data fetching hook for the staff management list.
 *
 * Handles:
 * - Initial data load via GET /api/users (paginated)
 * - Debounced search filtering by name
 * - Pagination state management (25 per page by default)
 * - Loading and error states
 */

import { useState, useEffect, useCallback, useRef } from 'react'
import { fetchStaffMembers } from '../api.js'
import type { StaffMemberDetail, StaffPaginatedResponse } from '../types.js'

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

const DEFAULT_PAGE_SIZE = 25
const SEARCH_DEBOUNCE_MS = 300

// ---------------------------------------------------------------------------
// Hook State & Actions Interfaces
// ---------------------------------------------------------------------------

interface UseStaffMembersState {
  /** Paginated staff member data */
  staffMembers: StaffMemberDetail[]
  /** Total number of matching staff members (for pagination) */
  totalItems: number
  /** Current page number (1-indexed) */
  currentPage: number
  /** Items per page */
  pageSize: number
  /** Total pages based on current search results */
  totalPages: number
  /** Current search term */
  searchTerm: string
  /** Whether data is currently being fetched */
  isLoading: boolean
  /** Error message from failed API calls, or null */
  error: string | null
}

interface UseStaffMembersActions {
  /** Set the search term (triggers debounced fetch) */
  setSearchTerm: (term: string) => void
  /** Navigate to a specific page */
  goToPage: (page: number) => void
  /** Reset pagination to page 1 and refetch */
  refresh: () => void
}

export type UseStaffMembersResult = UseStaffMembersState & UseStaffMembersActions

// ---------------------------------------------------------------------------
// Hook Implementation
// ---------------------------------------------------------------------------

/**
 * Custom hook for fetching and managing the staff member list.
 *
 * Provides paginated results with debounced search filtering by name.
 */
export function useStaffMembers(): UseStaffMembersResult {
  const [staffMembers, setStaffMembers] = useState<StaffMemberDetail[]>([])
  const [totalItems, setTotalItems] = useState(0)
  const [currentPage, setCurrentPage] = useState(1)
  const [pageSize] = useState(DEFAULT_PAGE_SIZE)
  const [searchTerm, setSearchTermState] = useState('')
  const [isLoading, setIsLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)

  // Ref for debounce timer
  const searchTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null)

  // Debounced search term — actual value used in API calls
  const [debouncedSearchTerm, setDebouncedSearchTerm] = useState('')

  // -----------------------------------------------------------------------
  // Data fetching
  // -----------------------------------------------------------------------

  const fetchStaffData = useCallback(async () => {
    setIsLoading(true)
    setError(null)

    try {
      const response: StaffPaginatedResponse = await fetchStaffMembers({
        search: debouncedSearchTerm || undefined,
        page: currentPage,
        pageSize,
      })

      setStaffMembers(response.users)
      setTotalItems(response.totalItems)
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to load staff members'
      setError(message)
      setStaffMembers([])
      setTotalItems(0)
    } finally {
      setIsLoading(false)
    }
  }, [debouncedSearchTerm, currentPage, pageSize])

  // -----------------------------------------------------------------------
  // Search debouncing
  // -----------------------------------------------------------------------

  const setSearchTerm = useCallback((term: string) => {
    setSearchTermState(term)

    // Clear existing timer
    if (searchTimerRef.current) {
      clearTimeout(searchTimerRef.current)
    }

    // Set new debounce timer
    searchTimerRef.current = setTimeout(() => {
      setDebouncedSearchTerm(term)
      // Reset to page 1 when search changes
      setCurrentPage(1)
    }, SEARCH_DEBOUNCE_MS)
  }, [])

  // -----------------------------------------------------------------------
  // Pagination
  // -----------------------------------------------------------------------

  const goToPage = useCallback((page: number) => {
    setCurrentPage(page)
  }, [])

  const refresh = useCallback(() => {
    fetchStaffData()
  }, [fetchStaffData])

  // -----------------------------------------------------------------------
  // Derived state
  // -----------------------------------------------------------------------

  const totalPages = Math.max(1, Math.ceil(totalItems / pageSize))

  // -----------------------------------------------------------------------
  // Effects
  // -----------------------------------------------------------------------

  // Fetch data when search term or page changes
  useEffect(() => {
    fetchStaffData()
  }, [fetchStaffData])

  // Cleanup debounce timer on unmount
  useEffect(() => {
    return () => {
      if (searchTimerRef.current) {
        clearTimeout(searchTimerRef.current)
      }
    }
  }, [])

  // -----------------------------------------------------------------------
  // Return
  // -----------------------------------------------------------------------

  return {
    staffMembers,
    totalItems,
    currentPage,
    pageSize,
    totalPages,
    searchTerm,
    isLoading,
    error,
    setSearchTerm,
    goToPage,
    refresh,
  }
}

/**
 * StaffListPage — Management list page for staff members.
 *
 * Displays a searchable, paginated DataTable with columns for:
 * - Name
 * - Role badge (Mechanic/Manager)
 * - Hourly rate (displayed as currency €X.XX/h)
 * - Active status badge
 */

import { useStaffMembers } from '../hooks/useStaffMembers.js'
import type { StaffMemberDetail } from '../types.js'
import { formatHourlyRate } from '../types.js'
import {
  DataTable,
  type DataTableColumn,
} from '@/components/ui/DataTable.js'
import { Button } from '@/components/ui/button.js'

// ---------------------------------------------------------------------------
// Column Cell Components
// ---------------------------------------------------------------------------

function RoleBadge({ role }: { role: 'mechanic' | 'manager' }) {
  return (
    <span
      className={`inline-flex items-center rounded-full px-2.5 py-0.5 text-xs font-medium ${
        role === 'mechanic'
          ? 'bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-300'
          : 'bg-blue-100 text-blue-800 dark:bg-blue-900/30 dark:text-blue-300'
      }`}
    >
      {role === 'mechanic' ? 'Mechanic' : 'Manager'}
    </span>
  )
}

function ActiveBadge({ isActive }: { isActive: boolean }) {
  return (
    <span
      className={`inline-flex items-center rounded-full px-2.5 py-0.5 text-xs font-medium ${
        isActive
          ? 'bg-emerald-100 text-emerald-800 dark:bg-emerald-900/30 dark:text-emerald-300'
          : 'bg-gray-100 text-gray-800 dark:bg-gray-700 dark:text-gray-300'
      }`}
    >
      {isActive ? 'Active' : 'Inactive'}
    </span>
  )
}

// ---------------------------------------------------------------------------
// Page Component
// ---------------------------------------------------------------------------

export function StaffListPage() {
  const {
    staffMembers,
    totalItems,
    currentPage,
    pageSize,
    searchTerm,
    isLoading,
    error,
    setSearchTerm,
    goToPage,
    refresh,
  } = useStaffMembers()

  // -----------------------------------------------------------------------
  // Column definitions for DataTable
  // ---------------------------------------------------------------------------

  const columns: DataTableColumn<StaffMemberDetail>[] = [
    {
      key: 'name',
      header: 'Name',
      render: (staff: StaffMemberDetail) => (
        <span className="font-medium">{staff.name}</span>
      ),
    },
    {
      key: 'role',
      header: 'Role',
      render: (staff: StaffMemberDetail) => (
        <RoleBadge role={staff.role} />
      ),
    },
    {
      key: 'hourlyRate',
      header: 'Hourly Rate',
      render: (staff: StaffMemberDetail) => (
        <span>{formatHourlyRate(staff.hourlyRate)}</span>
      ),
    },
    {
      key: 'isActive',
      header: 'Status',
      render: (staff: StaffMemberDetail) => (
        <ActiveBadge isActive={staff.isActive} />
      ),
    },
  ]

  // -----------------------------------------------------------------------
  // Render
  // ---------------------------------------------------------------------------

  return (
    <div className="space-y-6">
      {/* Page header */}
      <div>
        <h1 className="text-2xl font-bold tracking-tight">Staff Members</h1>
        <p className="text-muted-foreground mt-1">
          View and manage your team roster. Search by name to find specific staff members.
        </p>
      </div>

      {/* Error banner */}
      {error && (
        <div className="rounded-lg border border-red-200 bg-red-50 p-4 text-sm text-red-700 dark:border-red-800 dark:bg-red-900/20 dark:text-red-300">
          <p className="font-medium">Error loading staff members</p>
          <p>{error}</p>
          <Button variant="outline" size="sm" onClick={refresh} className="mt-2">
            Retry
          </Button>
        </div>
      )}

      {/* DataTable */}
      <DataTable<StaffMemberDetail>
        data={staffMembers}
        columns={columns}
        searchTerm={searchTerm}
        onSearchChange={setSearchTerm}
        totalItems={totalItems}
        currentPage={currentPage}
        pageSize={pageSize}
        onPageChange={goToPage}
        isLoading={isLoading}
        emptyMessage="No staff members found"
      />
    </div>
  )
}

import { NavLink } from 'react-router-dom'
import { useAppStore } from '@/app/store'
import {
  ChevronLeft,
  ChevronRight,
  Home,
  ReceiptText,
  PackageSearch,
  Package,
  Users,
  Wrench,
  FileText,
  type LucideIcon,
} from 'lucide-react'
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from '@radix-ui/react-tooltip'

const navItems = [
  { to: '/', icon: Home, label: 'Home' },
  { to: '/pos', icon: ReceiptText, label: 'POS' },
  { to: '/sales', icon: ReceiptText, label: 'Sales History' },
  { to: '/customers', icon: Users, label: 'Customers' },
  { to: '/staff', icon: Users, label: 'Staff' },
  { to: '/repairs', icon: Wrench, label: 'Repairs' },
  { to: '/quotes', icon: FileText, label: 'Quotes' },
  { to: '/catalog/parts', icon: Package, label: 'Catalog' },
  { to: '/products/dst-search', icon: PackageSearch, label: 'Product Finder' },
